#ef-menu.gtbg-menu-panel { top: calc(100% + 8px); }
    /* ===== shell pass: Extra Features overlay + phone onboarding (group SHELL, tools/t0/patches/SHELL.json) ===== */
    /* Layering: above the app toolbar (100/200) and its panels, BELOW every modal layer (Walkthrough 500, Help/Bookmarks 600, onboarding 1000).  It used to be 999999, above all of them. */
    #extra-features { z-index: 450; flex-wrap: wrap; justify-content: flex-end; max-width: calc(100vw - 28px); }
    /* while a modal or full-screen layer is open the pills step out of the way (script below sets html.gtbg-modal-open) */
    html.gtbg-modal-open #extra-features { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }
    /* the menu: height and side come from the fit script (scrolls inside, opens upward when the cluster sits low, stays inside the viewport) */
    #ef-menu.gtbg-menu-panel { overscroll-behavior: contain; scrollbar-width: thin; }
    #ef-menu.gtbg-menu-panel.gtbg-up { transform-origin: bottom right; }
    #ef-menu.gtbg-menu-panel:focus-visible { outline-offset: -2px; }
    /* Phone view: the way back from the desktop layout, shown only where the phone layout would have been chosen (touch, narrow / short) */
    #ef-layout {
      display: none; align-items: center; gap: 7px; flex: none;
      background: #12121e; color: #c9a24b; border: 1px solid #c9a24b; border-radius: 20px;
      padding: 7px 14px; font: inherit; font-size: 13px; font-weight: bold; cursor: pointer;
    }
    #ef-layout:hover { background: #1a1a2a; }
    #ef-layout .gicon { width: 15px; height: 15px; }
    @media (max-width: 834px) and (pointer: coarse), (max-height: 480px) and (pointer: coarse) { html[data-layout="desktop"] #ef-layout { display: flex; } }
    /* phone onboarding: the dock (Play, scrubber, speed) stays undimmed and reachable so "Tap Play at the bottom" can be done; only the card itself takes touches */
    html[data-layout="mobile"] div[style*="z-index: 1000"][style*="rgba(0, 0, 0, 0.85)"] { bottom: calc(var(--gt-dock) + var(--gt-sab)) !important; background: rgba(0, 0, 0, 0.6) !important; pointer-events: none !important; }
    html[data-layout="mobile"] div[style*="z-index: 1000"][style*="rgba(0, 0, 0, 0.85)"] > div { pointer-events: auto; max-height: 100% !important; }

menu.setAttribute('role', 'group'); menu.setAttribute('aria-label', 'Extra features menu'); menu.tabIndex = 0;

        function closeMenu() { menu.classList.remove('open'); btn.setAttribute('aria-expanded', 'false'); }
        // Menu fit: the panel is 684 px of menu; in a cluster at mid-height its lower groups ended below the screen and could not be reached.
        // Its height is now what the screen really has (never more than the content), it scrolls inside, opens upward when the cluster sits
        // low, and stays inside the viewport sideways.  Re-run on open, resize and whenever the cluster moves.
        function fitMenu() {
          if (!menu.classList.contains('open')) return;
          var ov = document.getElementById('extra-features'), r = ov.getBoundingClientRect();
          var vw = window.innerWidth, vh = window.innerHeight, pad = 12, gap = 8;
          menu.style.maxHeight = 'none';
          var want = menu.scrollHeight + 2;
          var below = vh - r.bottom - gap - pad, above = r.top - gap - pad;
          var up = below < Math.min(want, 360) && above > below;
          var room = Math.max(120, up ? above : below);
          menu.style.maxHeight = Math.floor(Math.min(room, want)) + 'px';
          menu.classList.toggle('gtbg-up', up);
          menu.style.top = up ? 'auto' : (r.height + gap) + 'px';
          menu.style.bottom = up ? (r.height + gap) + 'px' : 'auto';
          var w = menu.offsetWidth || Math.min(0.94 * vw, 460);
          menu.style.left = (Math.min(Math.max(r.right - w, pad), Math.max(pad, vw - w - pad)) - r.left) + 'px';
          menu.style.right = 'auto';
        }
        function openMenu() { menu.classList.add('open'); btn.setAttribute('aria-expanded', 'true'); fitMenu(); }
        window.GTBG_FIT_EF_MENU = fitMenu; window.GTBG_CLOSE_EF_MENU = closeMenu;

document.addEventListener('keydown', function (e) {
          if (!menu.classList.contains('open')) return;
          if (e.key === 'Escape') { var inside = menu.contains(document.activeElement); closeMenu(); if (inside) btn.focus(); return; }
          if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp' && e.key !== 'Home' && e.key !== 'End') return;
          var items = Array.prototype.slice.call(menu.querySelectorAll('a.gtbg-item')), i = items.indexOf(document.activeElement);
          if (i < 0 && document.activeElement !== btn && document.activeElement !== menu) return;
          e.preventDefault();
          items[e.key === 'Home' ? 0 : e.key === 'End' ? items.length - 1 : e.key === 'ArrowDown' ? (i + 1) % items.length : (i <= 0 ? items.length - 1 : i - 1)].focus();
        });

// ---- shell pass -----------------------------------------------------------------------------------------------------
      function refit() { if (window.GTBG_FIT_EF_MENU) window.GTBG_FIT_EF_MENU(); }

      // 0. Placement.  The cluster goes where it overlaps the least, measured against what is really on screen: every button / link / input, every
      //    leaf of text and, heavily, every floating panel (position fixed/absolute, z-index >= 80: cards, search, filter, legend, minimap, unit panel).
      //    Positions: the right edge, then the left edge, top to bottom in 16 px steps; ties and near-ties keep the current spot (no hopping).
      //    Floating panels that came and went within the last two minutes stay on the map as obstacles (cards, toasts, the story panel appear
      //    on their own while it plays): the cluster settles outside all of them once instead of hopping every time one shows up.
      var seenPanels = [];
      function obstacles() {
        var out = [], root = document.getElementById('root'), vw = window.innerWidth, vh = window.innerHeight, now = Date.now(), live = {};
        if (!root) return out;
        var all = root.querySelectorAll('*');
        for (var i = 0; i < all.length; i++) {
          var el = all[i], tag = el.tagName;
          if (tag === 'CANVAS' || overlay.contains(el)) continue;
          var r = el.getBoundingClientRect();
          if (r.width < 2 || r.height < 2 || r.bottom < 0 || r.top > vh || r.right < 0 || r.left > vw) continue;
          var cs = getComputedStyle(el);
          if (cs.visibility === 'hidden' || cs.display === 'none' || +cs.opacity < 0.05) continue;
          var wt = 0;
          if (tag === 'BUTTON' || tag === 'A' || tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA' || /^(button|checkbox|switch|dialog|slider)$/.test(el.getAttribute('role') || '')) wt = 8;
          else if (el.children.length === 0 && (el.textContent || '').trim().length > 1) wt = 1;
          if ((cs.position === 'fixed' || cs.position === 'absolute') && parseInt(cs.zIndex, 10) >= 80 && r.width >= 90 && r.height >= 36 &&
              !(r.width >= vw * 0.9 && r.height >= vh * 0.9)) wt = Math.max(wt, 30);
          if (wt) out.push({ l: r.left, t: r.top, r: r.right, b: r.bottom, w: wt });
          if (wt >= 30) {
            var key = Math.round(r.left / 8) + ',' + Math.round(r.top / 8) + ',' + Math.round(r.width / 16) + ',' + Math.round(r.height / 16);
            live[key] = 1;
            var known = false;
            for (var m = 0; m < seenPanels.length; m++) if (seenPanels[m].key === key) { seenPanels[m].at = now; known = true; break; }
            if (!known) seenPanels.push({ key: key, l: r.left, t: r.top, r: r.right, b: r.bottom, at: now });
          }
        }
        seenPanels = seenPanels.filter(function (p) { return now - p.at < 120000; }).slice(-40);
        for (var q = 0; q < seenPanels.length; q++) {
          var p = seenPanels[q];
          if (!live[p.key]) out.push({ l: p.l, t: p.t, r: p.r, b: p.b, w: 30 });
        }
        return out;
      }
      function costAt(obs, l, t, w, h) {
        var c = 0;
        for (var i = 0; i < obs.length; i++) { var o = obs[i]; if (!(l + w <= o.l || l >= o.r || t + h <= o.t || t >= o.b)) c += o.w; }
        return c;
      }
      function reposition() {
        if (!overlay || !overlay.classList.contains('gtbg-visible') || modalWas) return;
        var cur = overlay.getBoundingClientRect(), w = cur.width, h = cur.height, vw = window.innerWidth, vh = window.innerHeight;
        if (!w || !h) return;
        var obs = obstacles(), here = costAt(obs, cur.left, cur.top, w, h);
        var best = null, bestCost = Infinity, M = parseInt(MARGIN, 10) || 14, top0 = parseInt(TOP, 10) || 60, ys = [];
        for (var y = top0; y + h <= vh - M; y += 16) ys.push(y);
        ys.push(Math.max(top0, vh - M - h));
        for (var s = 0; s < 2; s++) {
          var l = s === 0 ? Math.max(M, vw - M - w) : M;
          for (var k = 0; k < ys.length; k++) {
            var c = costAt(obs, l, ys[k], w, h) + s * 0.5 + (ys[k] - top0) / vh * 0.3;     // ties: top of the right edge, then down, then the left edge
            if (c < bestCost) { bestCost = c; best = { top: ys[k], right: s === 0, left: l }; }
          }
        }
        if (!best || here <= bestCost + 0.6) { refit(); return; }                          // already as good as it gets: stay put
        applyPosition(best.right ? { top: best.top + 'px', right: M + 'px', left: 'auto' } : { top: best.top + 'px', left: M + 'px', right: 'auto' });   // the stylesheet's right: 14px must not stretch a left-anchored box
        refit();
      }
      window.GTBG_REPOSITION_EF = reposition;

      // 1. Modal awareness.  A modal (Help, Bookmarks, the onboarding dialog) or a full-screen layer (Virtual Walkthrough) hides the pills;
      //    they used to float above the backdrop (z-index 999999) and over the content.  Detection is structural, not text matching.
      var rootEl = null, modalWas = false, churnTimer = 0, churnLast = 0;
      function fullscreenLayer() {
        if (!rootEl) return false;
        var els = rootEl.querySelectorAll(':scope > *, :scope > * > *'), vw = window.innerWidth, vh = window.innerHeight;
        for (var i = 0; i < els.length; i++) {
          var cs = getComputedStyle(els[i]);
          if (cs.position !== 'fixed' || !(parseInt(cs.zIndex, 10) >= 400)) continue;
          var r = els[i].getBoundingClientRect();
          if (r.width >= vw * 0.9 && r.height >= vh * 0.9) return true;
        }
        return false;
      }
      function modalOpen() { return !!document.querySelector('.gtbg-modal-overlay, [role="dialog"][aria-modal="true"]') || fullscreenLayer(); }
      function syncModal() {
        var open = modalOpen();
        if (open === modalWas) return open;
        modalWas = open;
        document.documentElement.classList.toggle('gtbg-modal-open', open);
        if (open && window.GTBG_CLOSE_EF_MENU) window.GTBG_CLOSE_EF_MENU();
        if (!open) setTimeout(reposition, 60);
        return open;
      }

      // 2. Layout churn.  Panels and cards that appear on their own (the story card at tick 14, toasts) are obstacles the click/resize hooks above never
      //    saw.  Element nodes added or removed under #root schedule one re-check (debounced, at most once a second); text updates never do.
      function onChurn(muts) {
        var el = false;
        for (var i = 0; i < muts.length && !el; i++) {
          for (var k = 0; k < 2 && !el; k++) {
            var list = k ? muts[i].removedNodes : muts[i].addedNodes;
            for (var j = 0; j < list.length; j++) if (list[j].nodeType === 1) { el = true; break; }
          }
        }
        if (!el) return;
        clearTimeout(churnTimer);
        churnTimer = setTimeout(function () {
          if (document.hidden) return;
          churnLast = Date.now();
          if (!syncModal()) reposition();
        }, Math.max(300, 1000 - (Date.now() - churnLast)));
      }
      window.addEventListener('resize', function () { setTimeout(function () { syncModal(); refit(); }, 200); });
      document.addEventListener('click', function () { setTimeout(syncModal, 200); }, true);
      function startShell() {                       // this script runs before <main id="root"> is parsed
        rootEl = document.getElementById('root');
        if (rootEl && window.MutationObserver) new MutationObserver(onChurn).observe(rootEl, { childList: true, subtree: true });
        syncModal();
      }
      if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', startShell); else startShell();

      // 3. Phone view: the way back from the desktop layout (a window event the app listens to; it also forgets the layout override and ?layout=)
      var phoneBtn = document.getElementById('ef-layout');
      if (phoneBtn) phoneBtn.addEventListener('click', function () {
        try { window.dispatchEvent(new CustomEvent('gtbg-layout', { detail: 'mobile' })); } catch (e) {}
      });
